parameters.jsCode:
// Deterministic checks. The agent's output is a proposal; nothing here trusts it
// without comparing against config or a fresh read of the system of record.
const cfg = $('Config').first().json;
const out = $('Invoice exception agent').item.json.output ?? null;
const reasons = [];
if (!out) reasons.push('agent_produced_no_valid_output');
if (out && !(typeof out.confidence === 'number' && out.confidence >= cfg.min_confidence)) {
  reasons.push('confidence ' + out?.confidence + ' below ' + cfg.min_confidence);
}

const req = $('Normalize exception').item.json;
const m = $json; // fresh three-way match view: { status, lines: [{ line, received_qty, invoiced_qty, po_unit_price, invoiced_unit_price }] }
const lines = m.lines ?? [];

// Recompute the variance here instead of trusting the agent's arithmetic.
let variance = 0;
let poValue = 0;
for (const l of lines) {
  if (l.invoiced_qty > l.received_qty) reasons.push('line ' + l.line + ' invoiced ' + l.invoiced_qty + ' but received ' + l.received_qty);
  variance += (l.invoiced_unit_price - l.po_unit_price) * l.invoiced_qty;
  poValue += l.po_unit_price * l.invoiced_qty;
}
const pct = poValue > 0 ? (variance / poValue) * 100 : Infinity;

if (!lines.length) reasons.push('match view returned no lines');
if (m.status !== 'match_exception') reasons.push('invoice status is now ' + m.status);
if (variance < 0) reasons.push('invoice is under PO price; confirm with the vendor before approving');
if (Math.abs(variance) > cfg.max_auto_variance_amount) reasons.push('variance ' + variance.toFixed(2) + ' above ' + cfg.max_auto_variance_amount);
if (Math.abs(pct) > cfg.price_tolerance_pct) reasons.push('variance ' + pct.toFixed(2) + '% above ' + cfg.price_tolerance_pct + '%');
if (out?.duplicate_of_invoice_id) reasons.push('agent flagged a possible duplicate');
if (out && Math.abs((out.total_variance_amount ?? 0) - variance) > 0.01) reasons.push('agent variance ' + out.total_variance_amount + ' differs from recomputed ' + variance.toFixed(2));

const ok = reasons.length === 0;
return {
  json: {
    business_key: req.business_key,
    route: ok ? 'auto' : 'escalate',
    guardrail_reasons: reasons,
    variance: Number(variance.toFixed(2)),
    variance_pct: Number(pct.toFixed(3)),
    planned_actions: ok ? [{ action: 'erp.approve_invoice', invoice_id: req.invoice_id, variance: Number(variance.toFixed(2)) }] : [],
  },
};

const ok = $json.status === 'approved';
return {
  json: {
    verified: ok,
    verify_failed: !ok,
    verify_detail: ok ? '' : 'invoice status is ' + $json.status + ' after approval call',
  },
};

// Collects everything a reviewer needs in one record: the request, what the agent
// proposed, why the guardrails stopped it, and the tool calls behind it.
const intake = $('Normalize exception').item.json;
let agent = null;
let guard = null;
try { agent = $('Invoice exception agent').item.json; } catch (e) {}
try { guard = $('Guardrails').item.json; } catch (e) {}

const reasons = [...(guard?.guardrail_reasons ?? [])];
if ($json.error) reasons.push('system_error: ' + ($json.error.message ?? JSON.stringify($json.error)).slice(0, 300));
if ($json.verify_failed) reasons.push('verification_failed: ' + $json.verify_detail);
if ($json.handoff_reason) reasons.push($json.handoff_reason);
if (!agent?.output && !reasons.length) reasons.push('agent_produced_no_valid_output');
if (!reasons.length) {
  const o = agent.output;
  reasons.push('agent recommends review: ' + (o.decision ?? o.recommended_action ?? o.classification ?? o.route_to_queue ?? 'see proposal'));
}

const trace = (agent?.intermediateSteps ?? []).map((s) => ({
  tool: s.action?.tool,
  input: s.action?.toolInput,
  observation: String(s.observation ?? '').slice(0, 1500),
}));

return {
  json: {
    business_key: intake.business_key,
    team: "AP clerks",
    reasons,
    proposed: agent?.output ?? null,
    confidence: agent?.output?.confidence ?? null,
    questions: agent?.output?.questions_for_human ?? [],
    trace,
    summary: 'Invoice ' + intake.invoice_id + ' (PO ' + intake.po_number + ') · ' + (agent?.output?.exception_type ?? 'unknown') + ' · recommends ' + (agent?.output?.recommended_action ?? 'review') + ' · vendor email drafted',
  },
};

